    capacity: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Counts, storage and memory */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        counts: {
                            /** @description Issues not deleted */
                            issues: number;
                            /** @description Not in a completed or canceled state */
                            open_issues: number;
                            projects: number;
                            /** @description Key of the project with the most issues ("" if none) */
                            largest_project: string;
                            largest_project_issues: number;
                            /** @description Active people and agents */
                            users: number;
                            /** @description History entries */
                            activities: number;
                        };
                        storage: {
                            /** @description The SQLite file with its -wal and -shm */
                            db_bytes: number | null;
                            backups_bytes: number | null;
                            /** @description Everything under the data directory */
                            data_dir_bytes: number | null;
                            disk_total_bytes: number | null;
                            /** @description Available to the server's user */
                            disk_free_bytes: number | null;
                        };
                        memory: {
                            /** @description Memory obtained from the OS by the server process */
                            sys_bytes: number;
                            heap_bytes: number;
                        };
                        /** Format: date-time */
                        measured_at: string;
                    };
                };
            };
            403: components["responses"]["Error"];
        };
    };
